text:
li {
  &.activitygroup {
    display: block;
  }

  &.activityitem {
    display: grid;
    grid-template:
      "icon display time" auto
      "icon progress progress" auto
      "icon status status" 1fr / auto 1fr auto;
    align-items: baseline;
  }
}

.activityitem {
  padding: 7px 4px;
  border-block-end: 1px solid var(--field-border-color);

  .activitygroup-list & {
    padding-inline-start: 12px;
  }

  & > img {
    inline-size: 48px;
    block-size: 48px;
    grid-area: icon;
    align-self: start;
  }

  & > .displayText {
    grid-area: display;
  }

  & > .dateTime {
    grid-area: time;
  }

  & > .progressmeter {
    grid-area: progress;
  }

  & > .statusText {
    grid-area: status;
  }
